  <script>
    const products = [
      { name: "Aster Overshirt", price: "$148", category: "new", tag: "Lightweight layer", note: "Relaxed fit · brushed cotton", accent: "A1" },
      { name: "Orbit Runner", price: "$126", category: "bestseller", tag: "Best seller", note: "Responsive sole · all-day comfort", accent: "OR" },
      { name: "Signal Tote", price: "$92", category: "new", tag: "Editor pick", note: "Structured carry · recycled nylon", accent: "ST" },
      { name: "Nocturne Hoodie", price: "$118", category: "bestseller", tag: "Core staple", note: "Heavyweight fleece · soft hand feel", accent: "NH" },
      { name: "Midline Cargo", price: "$132", category: "new", tag: "Fresh drop", note: "Utility pockets · tapered leg", accent: "MC" },
      { name: "Luxe Cap", price: "$54", category: "bestseller", tag: "Low stock", note: "Minimal branding · matte finish", accent: "LC" }
    ];

    const productGrid = document.getElementById("productGrid");
    const searchInput = document.getElementById("searchInput");
    const newsletterForm = document.querySelector(".newsletter-form");
    const newsletterStatus = document.getElementById("newsletterStatus");
    const filterButtons = [...document.querySelectorAll(".filter-btn")];
    let activeFilter = "all";

    function renderProducts() {
      const query = searchInput.value.trim().toLowerCase();
      const visible = products.filter((product) => {
        const matchesFilter = activeFilter === "all" || product.category === activeFilter;
        const matchesQuery = !query || [product.name, product.tag, product.note].join(" ").toLowerCase().includes(query);
        return matchesFilter && matchesQuery;
      });

      productGrid.innerHTML = visible.map((product) => `
        <article class="product-card">
          <div class="product-media" aria-hidden="true">
            <div class="brand-mark" style="width:84px;height:84px;border-radius:26px;font-size:1.1rem;">${product.accent}</div>
          </div>
          <h3 class="product-name">${product.name}</h3>
          <div class="product-meta">
            <span>${product.note}</span>
            <span class="price">${product.price}</span>
          </div>
          <div class="tag-row">
            <span class="tag">${product.tag}</span>
            <span class="tag">${product.category}</span>
          </div>
        </article>
      `).join("");

      if (!visible.length) {
        productGrid.innerHTML = `
          <div class="side-card" style="grid-column:1/-1;">
            <h3>No products found</h3>
            <p>Try a different search term or clear the current filter.</p>
          </div>
        `;
      }
    }

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        activeFilter = button.dataset.filter;
        filterButtons.forEach((item) => item.classList.toggle("active", item === button));
        renderProducts();
      });
    });

    searchInput.addEventListener("input", renderProducts);

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();
      newsletterStatus.textContent = "Thanks — you’re on the list.";
      newsletterForm.reset();
    });

    function renderCountdown() {
      const target = new Date();
      target.setHours(target.getHours() + 18, 0, 0, 0);

      const update = () => {
        const diff = Math.max(0, target - new Date());
        const hours = Math.floor(diff / 36e5);
        const minutes = Math.floor((diff % 36e5) / 6e4);
        const seconds = Math.floor((diff % 6e4) / 1000);
        const days = Math.floor(hours / 24);
        const remainHours = hours % 24;

        document.getElementById("countdown").innerHTML = `
          <div class="timebox"><strong>${String(days).padStart(2, "0")}</strong><span>Days</span></div>
          <div class="timebox"><strong>${String(remainHours).padStart(2, "0")}</strong><span>Hours</span></div>
          <div class="timebox"><strong>${String(minutes).padStart(2, "0")}</strong><span>Min</span></div>
          <div class="timebox"><strong>${String(seconds).padStart(2, "0")}</strong><span>Sec</span></div>
        `;
      };

      update();
      setInterval(update, 1000);
    }

    renderProducts();
    renderCountdown();
  </script>
